<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
import DojoIcon from './DojoIcon.vue';
const props=defineProps({batch:{type:Boolean,default:false}});
const emit=defineEmits(['close','updated']);
const batchResults=ref([]),progress=ref(null);let progressTimer;
function rememberedRisk(){try{return sessionStorage.getItem('dojo-mail-risk')==='1'}catch{return false}}
const busy=ref(false),windows=ref([]),chosen=ref(''),rows=ref([]),revision=ref(null),error=ref(''),message=ref(''),warnings=ref([]),ack=ref(rememberedRisk()),role=ref(''),from=ref(''),to=ref('');
const fallbackNames={200001:'太阴符咒',200002:'太阴符咒',410:'契约书·招福达摩',490001:'神秘的符咒（蓝票）',490002:'破碎的符咒',900001:'金币',900007:'百鬼夜行门票',900090:'功勋',900016:'勋章'};
const names=computed(()=>Object.assign({},fallbackNames,...rows.value.map(r=>r.item_names||{})));
const meta=computed(()=>Object.assign({},...rows.value.map(r=>r.item_meta||{})));
const itemName=id=>{const x=meta.value[id]||{};const name=x.name||names.value[id]||'名称待识别';return name+(x.stars?` · ${x.stars}星`:x.kind==='realm_card'?' · 星级待识别':'')};
const options=computed(()=>[...new Map(rows.value.map(r=>[r.role_id,r.label])).entries()]);
const filtered=computed(()=>rows.value.filter(r=>(!role.value||r.role_id===role.value)&&(!from.value||r.date>=from.value)&&(!to.value||r.date<=to.value)).sort((a,b)=>b.time-a.time));
const totals=computed(()=>{const m=new Map();for(const row of filtered.value)for(const i of row.items)m.set(i[0],(m.get(i[0])||0)+i[1]);return [...m].sort((a,b)=>a[0]-b[0]);});
async function call(action,payload={}){const r=await window.pywebview.api.blue_mail(action,payload);if(!r.ok)throw Error(r.error);return r.data;}
async function refresh(){busy.value=true;error.value='';try{const snapshot=await window.pywebview.api.blue_mail('archives');if(!snapshot.ok)throw Error(snapshot.error);revision.value=snapshot.data.revision;rows.value=(await call('records')).filter(r=>r.type!==400175);windows.value=await call('list');chosen.value=windows.value.some(w=>String(w.pid)===chosen.value)?chosen.value:String(windows.value[0]?.pid||'');}catch(e){error.value=e.message}finally{busy.value=false}}
async function read(){if(!ack.value||busy.value)return;const win=windows.value.find(w=>String(w.pid)===chosen.value);if(!win)return;busy.value=true;error.value='';message.value='';warnings.value=[];try{const r=await call('read',{...win,revision:revision.value,confirm:true});revision.value=r.snapshot.revision;message.value=`${r.label}：已保存 ${r.added} 封，跳过重复 ${r.duplicates} 封；当前已加载 ${r.loaded_count} 封邮件。`;warnings.value=r.warnings||[];rows.value=(await call('records')).filter(r=>r.type!==400175);emit('updated');if(!r.loaded_count)warnings.value.push('暂未读到邮件，请确认已进入庭院并稍后重试；这不表示没有奖励。');}catch(e){error.value=e.message}finally{busy.value=false}}
watch(ack,v=>{try{sessionStorage.setItem('dojo-mail-risk',v?'1':'0')}catch{}});
async function readAll(){if(!ack.value||busy.value)return;busy.value=true;error.value='';message.value='';warnings.value=[];batchResults.value=[];progress.value={done:0,total:windows.value.length};progressTimer=setInterval(async()=>{try{progress.value=await call('status')}catch{}},600);try{const result=await call('read_all',{revision:revision.value,confirm:true});revision.value=result.snapshot.revision;batchResults.value=result.results;message.value=`读取结束：成功 ${result.succeeded} 个窗口，失败 ${result.failed} 个；新增 ${result.added} 封，跳过重复 ${result.duplicates} 封。`;warnings.value=result.results.flatMap(r=>[...(r.warnings||[]),...(r.ok&&!r.loaded_count?[r.label+'：暂未读到邮件，不代表零产出']:[])]);rows.value=(await call('records')).filter(r=>r.type!==400175);emit('updated');}catch(e){error.value=e.message}finally{clearInterval(progressTimer);progressTimer=null;progress.value=null;busy.value=false}}
async function exportCsv(){busy.value=true;error.value='';try{const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const lines=[['角色','北京时间','邮件类型','资源名称','数量']];for(const r of filtered.value)for(const i of r.items)lines.push([r.label,new Date(r.time*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}),r.reason,itemName(i[0]),i[1]]);const result=await window.pywebview.api.blue_export({kind:'csv',filename:'道馆全部资源.csv',content:lines.map(r=>r.map(cell).join(',')).join('\r\n')});if(!result.ok)throw Error(result.error);}catch(e){error.value=e.message}finally{busy.value=false}}
function canLeave(){return !busy.value}defineExpose({canLeave});onMounted(async()=>{await refresh();if(props.batch&&ack.value&&!error.value)readAll()});onUnmounted(()=>clearInterval(progressTimer));
</script>
<template><Teleport to="body"><div class="mail-mask"><section class="mail-dialog" role="dialog" aria-modal="true" aria-label="道馆邮件与全部资源"><header><div><h2>道馆邮件与全部资源</h2><p>独立资源档案，无需在启动器绑定角色；按游戏身份与邮件去重，不领取或删除邮件。</p></div><button :disabled="busy" @click="emit('close')" aria-label="关闭邮件记录">×</button></header><div class="mail-content"><div class="mail-note">实验性进程内只读功能，可能导致客户端异常。只读取当前已加载邮件；已验证登录后无需打开邮箱即可读取。邮件发送日默认作为战斗日；旧蓝票记录暂不自动改写。</div><div class="mail-actions"><label>游戏窗口<select aria-label="游戏窗口" v-model="chosen" :disabled="busy"><option v-for="w in windows" :key="w.pid" :value="String(w.pid)">PID {{w.pid}}</option></select></label><button :disabled="busy" @click="refresh">刷新窗口与记录</button><button class="primary" :disabled="busy||!chosen||!ack" @click="read">{{busy?'正在处理…':'读取并自动记录'}}</button><button class="primary" :disabled="busy||!windows.length||!ack" @click="readAll">读取全部运行窗口</button><label><input type="checkbox" v-model="ack" :disabled="busy">了解实验性只读风险（本次运行记住选择）</label></div><p v-if="!busy&&!windows.length">未发现运行中的游戏窗口，请先启动游戏并进入庭院。</p><p v-if="progress" role="status">正在读取 {{progress.done||0}} / {{progress.total||0}} 个窗口，请稍候…</p><div v-if="batchResults.length"><p v-for="(r,index) in batchResults" :key="index">{{r.label||'游戏窗口'}}：{{r.ok?'新增 '+r.added+' 封 · 重复 '+r.duplicates+' 封':r.error}}</p></div><p class="mail-error" v-if="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p><ul v-if="warnings.length"><li v-for="s in warnings" :key="s">{{s}}</li></ul><div class="mail-actions"><label>角色<select v-model="role"><option value="">全部角色</option><option v-for="[id,label] in options" :key="id" :value="id">{{label}}</option></select></label><label>起始日期<input type="date" v-model="from"></label><label>结束日期<input type="date" v-model="to"></label><button :disabled="busy||!filtered.length" @click="exportCsv">导出全部资源 CSV</button></div><h3>资源合计 · {{filtered.length}} 封</h3><div class="mail-totals"><span v-for="[id,n] in totals" :key="id"><DojoIcon :id="Number(id)" />{{itemName(id)}} <b>{{n}}</b></span><span v-if="!totals.length">尚无记录，读取后在这里显示全部奖励。</span></div><div class="mail-table"><table><thead><tr><th>角色 / 北京时间</th><th>邮件类型</th><th>全部奖励</th></tr></thead><tbody><tr v-for="r in filtered" :key="r.scope+r.uid"><td>{{r.label}}<br>{{new Date(r.time*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</td><td>{{r.type===400179?'道馆场次奖励':'道馆相关奖励'}}</td><td><span v-for="(i,index) in r.items" :key="index" class="mail-item"><DojoIcon :id="i[0]" />{{itemName(i[0])}} × {{i[1]}}</span><span v-if="!r.items.length">奖励为空 / 未知</span></td></tr></tbody></table></div></div></section></div></Teleport></template>
<style scoped>
.mail-mask{position:fixed;inset:0;z-index:2000;background:#28231e70;display:flex;align-items:center;justify-content:center;padding:22px}.mail-dialog{display:flex;flex-direction:column;width:min(1160px,100%);max-height:calc(100dvh - 44px);background:#fffcf7;border:1px solid #decdb6;border-radius:12px;color:#3e382e;font:14px/1.6 "Microsoft YaHei UI","Microsoft YaHei",sans-serif}.mail-dialog header{display:flex;justify-content:space-between;gap:20px;padding:18px 24px;border-bottom:1px solid #e3d6c4}.mail-dialog h2,.mail-dialog p{margin:0}.mail-dialog h2{font-size:22px}.mail-dialog header p{font-size:13px;color:#74654f}.mail-content{padding:18px 24px;overflow:auto;min-height:0}.mail-note{padding:12px;background:#f6ecd8;border-radius:6px;color:#705b3e;font-size:13px}.mail-actions{display:flex;gap:12px;align-items:end;flex-wrap:wrap;margin:16px 0}.mail-actions label{display:flex;gap:6px;align-items:center;font-size:13px}.mail-actions select,.mail-actions input[type=date]{padding:7px;font:inherit;max-width:210px;background:#fff;border:1px solid #dac8b1;border-radius:5px}.mail-dialog button{font:inherit;padding:8px 12px;border:1px solid #d8c6ad;border-radius:5px;background:#f5eee2;color:#654d34;cursor:pointer}.mail-dialog button.primary{background:#725a40;color:white}.mail-dialog button:disabled{opacity:.5;cursor:default}.mail-error{color:#ac3c2e}.mail-totals{display:flex;gap:8px;flex-wrap:wrap}.mail-totals span{background:#edf1e9;border:1px solid #d5dfcf;border-radius:5px;padding:8px 12px}.mail-table{overflow:auto;margin-top:18px}.mail-table table{width:100%;border-collapse:collapse;text-align:left}.mail-table th,.mail-table td{padding:12px 8px;border-bottom:1px solid #e7ddcf;vertical-align:top}.mail-table small{font-size:12px;color:#7b6a54}.mail-item{display:inline-block;margin:0 12px 6px 0}
</style>
